      sourcesContent: [ "\n.category-manager {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n.batch-group-section {\n  padding: 12px;\n  background: var(--st-orb-bg-info-subtle);\n  border: 1px solid var(--st-orb-border-info-soft);\n  border-radius: 8px;\n}\n\n.batch-group-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 8px;\n}\n\n.batch-group-title {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-weight: 600;\n  color: var(--SmartThemeBodyColor);\n\n  i {\n    color: var(--SmartThemeQuoteColor);\n  }\n}\n\n.batch-group-count {\n  font-size: 12px;\n  color: color-mix(in srgb, var(--SmartThemeBodyColor) 70%, transparent);\n}\n\n.batch-group-hint {\n  font-size: 13px;\n  color: color-mix(in srgb, var(--SmartThemeBodyColor) 70%, transparent);\n  margin-bottom: 8px;\n}\n\n.batch-group-actions {\n  display: flex;\n  gap: 8px;\n  justify-content: flex-end;\n  margin-top: 12px;\n  padding-top: 12px;\n  border-top: 1px solid var(--SmartThemeBorderColor);\n}\n\n.category-options {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5em;\n  max-height: 240px;\n  overflow-y: auto;\n}\n\n.set-category-option {\n  // 基于原生 menu_button 样式\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 0.5em 0.75em;\n  white-space: nowrap;\n  flex-shrink: 0;\n\n  i {\n    flex-shrink: 0;\n  }\n\n  span:not(.category-color-dot) {\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n\n  // 选中状态样式 - 使用原生高亮效果\n  &.selected {\n    filter: brightness(1.2);\n    border-color: var(--SmartThemeQuoteColor) !important;\n    background: color-mix(in srgb, var(--SmartThemeQuoteColor) 15%, var(--black30a));\n  }\n}\n\n.set-category-modal {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n.set-category-hint {\n  font-size: 13px;\n  color: color-mix(in srgb, var(--SmartThemeBodyColor) 70%, transparent);\n\n  strong {\n    color: var(--SmartThemeBodyColor);\n  }\n}\n\n// 管理标签区域 - 仿原生样式\n.category-action-section {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  padding: 12px;\n  background: var(--SmartThemeBlurTintColor);\n  border: 1px solid var(--SmartThemeBorderColor);\n  border-radius: 10px;\n}\n\n.action-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 4px;\n}\n\n.action-title {\n  font-size: 14px;\n  font-weight: 600;\n  color: var(--SmartThemeBodyColor);\n}\n\n.new-category-row {\n  display: flex;\n  gap: 6px;\n  align-items: center;\n\n  .new-category-input {\n    flex: 1;\n    min-width: 0;\n  }\n}\n\n.color-picker {\n  width: 32px;\n  height: 32px;\n  border: 1px solid var(--SmartThemeBorderColor);\n  border-radius: 6px;\n  cursor: pointer;\n  padding: 2px;\n  flex-shrink: 0;\n  background: var(--SmartThemeBlurTintColor);\n  transition: border-color 0.15s ease;\n\n  &::-webkit-color-swatch-wrapper {\n    padding: 2px;\n  }\n\n  &::-webkit-color-swatch {\n    border: none;\n    border-radius: 4px;\n  }\n\n  &::-moz-color-swatch {\n    border: none;\n    border-radius: 4px;\n  }\n\n  &:hover {\n    border-color: var(--SmartThemeQuoteColor);\n  }\n\n  &:focus {\n    outline: none;\n    border-color: var(--SmartThemeQuoteColor);\n  }\n}\n\n.category-color-dot {\n  width: 12px;\n  height: 12px;\n  border-radius: 50%;\n  flex-shrink: 0;\n}\n" ],
