      sourcesContent: [ "\n.config-group-manager {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n.group-list {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  max-height: 400px;\n  overflow-y: auto;\n}\n\n.group-list-empty {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  padding: 32px;\n  color: color-mix(in srgb, var(--SmartThemeBodyColor) 60%, transparent);\n  text-align: center;\n\n  i {\n    font-size: 32px;\n    margin-bottom: 12px;\n    opacity: 0.5;\n  }\n\n  p {\n    margin: 4px 0;\n    font-size: 14px;\n  }\n\n  .hint {\n    font-size: 12px;\n    color: color-mix(in srgb, var(--SmartThemeBodyColor) 50%, transparent);\n  }\n}\n\n.group-list-item {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) auto;\n  align-items: center;\n  column-gap: 12px;\n  padding: 12px 14px;\n  background: var(--SmartThemeBlurTintColor);\n  border: 1px solid var(--SmartThemeBorderColor);\n  border-radius: 8px;\n  transition: border-color 0.2s;\n\n  &:hover {\n    border-color: var(--SmartThemeQuoteColor);\n  }\n}\n\n.group-info {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  flex: 1;\n  min-width: 0;\n}\n\n.group-header {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  flex-wrap: wrap;\n}\n\n.group-name {\n  font-weight: 600;\n  font-size: 14px;\n  color: var(--SmartThemeBodyColor);\n}\n\n.group-count {\n  font-size: 12px;\n  color: color-mix(in srgb, var(--SmartThemeBodyColor) 60%, transparent);\n  background: color-mix(in srgb, var(--SmartThemeBodyColor) 10%, transparent);\n  padding: 2px 8px;\n  border-radius: 10px;\n}\n\n.group-details {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  flex-wrap: wrap;\n  font-size: 12px;\n  color: color-mix(in srgb, var(--SmartThemeBodyColor) 70%, transparent);\n\n  i {\n    margin-right: 4px;\n    opacity: 0.7;\n  }\n}\n\n.group-url {\n  max-width: 280px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.group-actions {\n  display: flex;\n  flex-direction: row;\n  align-items: center;\n  gap: 6px;\n  flex-shrink: 0;\n  align-self: center;\n  justify-self: end;\n  margin-left: auto;\n}\n\n.group-actions :deep(.menu_button) {\n  margin: 0;\n}\n\n@media (max-width: 520px) {\n  .group-list-item {\n    grid-template-columns: 1fr;\n    row-gap: 10px;\n  }\n\n  .group-actions {\n    flex-direction: row;\n    justify-self: end;\n    margin-left: 0;\n  }\n}\n" ],
